# Generated by build.py from recipe.yml for recipe http-limit-upload-size. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'roomy' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'roomy/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'notes.txt'), "uploaded by curl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'ten.txt'), "123456789`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-uploads', '--user', 'alice:s3cret', '--max-filesize', '10', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o NUL -w "%{http_code}" --digest -u alice:s3cret -T notes.txt http://127.0.0.1:8080/notes.txt } finally { Stop-Process $server0 }
